def asal(m):
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True

for n in range(0, 45):
    if not asal(n*n + n + 41):
        print(n)
        break

def s(n):
    if n == 1:
        return 1
    return s(n - 1) + n

print(s(5))
print(s(10) == 10 * 11 // 2)

